              placeholder="Primary image URL"
            />
          </div>

          <div className="grid gap-3 rounded-2xl border border-[color:var(--border)] bg-[color:var(--surface-strong)] p-4 md:grid-cols-[10rem_1fr] md:items-center">
            <img
              src={form.imageUrl}
